package com.example.helpdesk.repo; import com.example.helpdesk.model.*; import org.springframework.data.jpa.repository.*; import java.util.*; public interface TicketRepository extends JpaRepository<Ticket,Long>{List<Ticket> findByReporterOrderByUpdatedAtDesc(User u); long countByStatus(TicketStatus s); long countByPriority(Priority p); @Query("select t from Ticket t where lower(t.title) like lower(concat('%',:q,'%')) or str(t.id)=:q order by t.updatedAt desc") List<Ticket> search(String q);}
